{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (0.00) and historical prices show downward momentum.",
    "Increase forecast sensitivity to recent price spikes — if last 3-5 days show sharp upward movement, avoid overshooting in next 5-7 days.",
    "Apply mean reversion bias: if forecast is significantly above 30-day moving average, reduce by 5-10% for next 3-5 days unless sentiment supports continuation.",
    "When sentiment is positive (e.g., 0.25), allow slight upward bias but cap forecast at +10% above recent 10-day high to avoid overcorrection.",
    "Correct for lag: if true outcome is significantly higher than forecast, adjust next forecast by +2-5% of the gap, especially if sentiment remains neutral or positive.",
    "Avoid overfitting to short-term volatility — if 30d forecast is erratic, use 18d history as anchor for smoothing."
  ]
}
